CREATE DATABASE IF NOT EXISTS flower_admin CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE flower_admin;
CREATE TABLE IF NOT EXISTS shops (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) NOT NULL, address VARCHAR(255), phone VARCHAR(30));
CREATE TABLE IF NOT EXISTS flowers (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(180) NOT NULL, price DECIMAL(14,2) NOT NULL DEFAULT 0, stock INT NOT NULL DEFAULT 0, image_path VARCHAR(500), description TEXT);
CREATE TABLE IF NOT EXISTS orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, buyer VARCHAR(150) NOT NULL, platform VARCHAR(80), delivery_address TEXT, phone VARCHAR(30), delivery_time VARCHAR(50), delivery_date DATE, flower_name VARCHAR(180), flower_id BIGINT NULL, shop_id BIGINT NULL, quantity INT NOT NULL DEFAULT 1, unit_price DECIMAL(14,2) NOT NULL DEFAULT 0, deposit DECIMAL(14,2) NOT NULL DEFAULT 0, card_note TEXT, status VARCHAR(80) NOT NULL DEFAULT 'Chưa chuẩn bị', image_path VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (flower_id) REFERENCES flowers(id) ON DELETE SET NULL, FOREIGN KEY (shop_id) REFERENCES shops(id) ON DELETE SET NULL);
